// Asserts that two integer arrays are equal in size and elements
void assert_array_equal(int *arr1, int *arr2, int size) {
    for (int i = 0; i < size; i++) {
        assert(arr1[i] == arr2[i]);
    }
}

// Asserts that an integer array is sorted in non-decreasing order
void assert_array_sorted(int *arr, int size) {
    for (int i = 1; i < size; i++) {
        assert(arr[i - 1] <= arr[i]);
    }
}

// Asserts that partition function correctly partitions the array around the pivot
void assert_partition_correct(int *arr, int low, int high, int pivot_index) {
    int pivot_value = arr[pivot_index];
    for (int i = low; i < pivot_index; i++) {
        assert(arr[i] <= pivot_value);
    }
    for (int i = pivot_index + 1; i <= high; i++) {
        assert(arr[i] >= pivot_value);
    }
}

